  "ei.h.aato": "ইয়াৰ পৰা ঠিক হয় ই-ইনভইচ আপোনাৰ বাবে প্ৰযোজ্য নে নাই, আৰু 30 দিনৰ সীমা প্ৰযোজ্য নে নাই। এইটো এই ব্ৰাউজাৰতে মনত থাকে।",
  "ev.hsn6": "আইটেম {n}: ই-ইনভইচত 6 বা 8 অংকৰ HSN/SAC ক’ড লাগিব (4 অংক কেৱল ₹5 কোটিৰ কম বিজনেছৰ বাবে, যিয়ে ই-ইনভইচ নকৰে)।",
  "ev.old30": "এই ইনভইচ 30 বা তাতকৈ বেছি দিন পুৰণি। ₹10 কোটি বা বেছি টাৰ্নঅভাৰত পৰ্টেলে ইয়াক এতিয়া ৰেজিষ্টাৰ নকৰে। নতুন ইনভইচ বনোৱাৰ আগতে আপোনাৰ একাউণ্টেণ্টক সোধক।",
  "ev.lt5": "ই-ইনভইচ আপোনাৰ বাবে বাধ্যতামূলক নহয়, যেতিয়ালৈকে 2017-18 ৰ পৰা কোনো বছৰ আপোনাৰ টাৰ্নঅভাৰ ₹5 কোটি পাৰ হোৱা নাই।",
  "ev.old180": "180 দিনতকৈ পুৰণি ডকুমেণ্টৰ ই-ৱে বিল পৰ্টেলে নবনায়।",
  "ev.smallst": "{st}ৰ ভিতৰত ই-ৱে বিল সাধাৰণতে ₹{v}তকৈ বেছি হ’লেহে লাগে (আন ৰাজ্যলৈ ₹50,000তকৈ বেছি; আন ৰাজ্যলৈ যোৱা জব ৱৰ্ক আৰু হস্তশিল্পত যিকোনো মূল্যত লাগে)।",
  "ev.fromirn": "আপোনাৰ বিজনেছে ই-ইনভইচ বনাব লগা হ’লে, এই ইনভইচৰ ই-ৱে বিল পৰ্টেলে কেৱল ইয়াৰ IRNৰ পৰা বনায়: “ই-ইনভইচৰ লগতে ই-ৱে বিলো বনাওক”ত টিক দিয়ক আৰু ই-ইনভইচ ফাইল বনাওক।",
  "ev.tidchk": "ট্ৰান্সপৰ্টাৰ IDৰ শেষৰ আখৰ মিলা নাই। টাইপৰ ভুল নেকি এবাৰ চাই লওক।",
  "ei.rmnote": "আপুনি এই IRN পৰ্টেলত কেন্সেল কৰিলে, এই ইনভইচ নম্বৰ আৰু কেতিয়াও ৰেজিষ্টাৰ নহ’ব। শুদ্ধ ইনভইচ নতুন নম্বৰেৰে বনাওক।",
