  "app.vault": "এই ব্ৰাউজাৰৰ ডেটা হোমত ছেভ আছে, যিটো Nivesh Sahayak-ৰ সকলো টুলত ভাগ কৰা। আমালৈ একো পঠিওৱা নহয়।",
  "app.help": "ই কেনেকৈ কাম কৰে",
  "app.helpp": "billing., cash-memo. আৰু credit-note.-ত বনোৱা বিল ইয়াত নিজে নিজে দেখা যায়। পোৱা আৰু দিয়া টকা ইয়াত লিখক; এপে সেইবোৰ বিলৰ সৈতে জোৰা লগায়, এডভান্স ৰাখে আৰু বাকী আৰু হাতৰ কেশ্ব উলিয়ায়।",
