  "g3.w.nogstin": "{p}-ৰ পাৰচেজ বিল {no}-ত চাপ্লায়াৰৰ বৈধ GSTIN নাই, গতিকে ইয়াৰ ITC GSTR-2B-ত নাহিব।",
