  "b2.gain": "লাভ {a}: একাউণ্টেণ্টক সোধক",
  "b2.farules": "ডেপ্ৰিচিয়েচন কেনেকৈ হিচাপ হয়",
  "b2.farule1": "হিচাপৰ ডেপ্ৰিচিয়েচন কোম্পানীজ এক্ট, 2013 ৰ চিডিউল II অনুসৰি: প্ৰতি প্ৰকাৰ এছেটৰ এটা ব্যৱহাৰৰ আয়ুস আছে (যেনে কম্পিউটাৰ 3 বছৰ, ফাৰ্ণিচাৰ 10 বছৰ, প্লেণ্ট আৰু মেচিনাৰী 15 বছৰ, কাৰ 8 বছৰ), বাকী মূল্য সাধাৰণতে দামৰ 5% তকৈ বেছি নহয়, আৰু বছৰৰ মাজত যোগ বা বিক্ৰী হোৱা এছেটত কেৱল ব্যৱহাৰৰ দিনকেইটাৰ ডেপ্ৰিচিয়েচন লাগে। ষ্ট্ৰেইট লাইন (SLM: প্ৰতি বছৰ সমান টকা) বা ৰিটেন ডাউন ভেলু (WDV: বাকী টকাত নিৰ্দিষ্ট ৰেট) বাছক। প্ৰ'প্ৰাইটৰ আৰু ফাৰ্মে প্ৰায়ে এই পদ্ধতিয়েই লয়; সিদ্ধান্ত আপোনাৰ একাউণ্টেণ্টৰ।",
  "b2.farule2": "ইনকাম টেক্স ডেপ্ৰিচিয়েচন প্ৰতি ব্লকৰ বেলেগে হিচাপ হয়: ব্লক ৰেটত ৰিটেন ডাউন ভেলু (যেনে প্লেণ্ট আৰু মেচিনাৰী 15%, ফাৰ্ণিচাৰ 10%, কম্পিউটাৰ 40%), বছৰত 180 দিনতকৈ কম ব্যৱহাৰ হোৱা এছেটত আধা ৰেট, আৰু বিক্ৰীৰ টকা ব্লকৰ পৰা কমে। এয়া কেৱল ইনকাম টেক্স ৰিটাৰ্ণৰ বাবে, হিচাপত কেতিয়াও ভৰোৱা নহয়। ভৰোৱা ৰেটবোৰ সাধাৰণ ব্লক ৰেট: আপোনাৰ একাউণ্টেণ্টৰ লগত নিশ্চিত হওক, বিশেষকৈ 1 এপ্ৰিল 2026 ৰ পৰা ইনকাম-টেক্স এক্ট, 2025 ৰ অধীনৰ বছৰবোৰৰ বাবে।",
  "b2.farule3": "আপুনি 'ডেপ্ৰিচিয়েচন ভৰাওক' টিপিলেহে ডেপ্ৰিচিয়েচন হিচাপলৈ যায়: বছৰৰ শেষ দিনৰ (বা বছৰৰ মাজত আজিৰ) জাৰ্নেল এণ্ট্ৰিয়ে ডেপ্ৰিচিয়েচনক ডেবিট কৰে আৰু প্ৰতিটো এছেট কমায়। পিছত এছেট সলনি কৰিলে আকৌ ভৰাওক, কেৱল পাৰ্থক্যহে যোগ হ'ব।",
