  "hp.biz": "আপোনাৰ বিজনেছৰ বিৱৰণ, যি ওপৰত ছপা হয়। পৰামৰ্শৰ পৰা ছেভ কৰা বিজনেছ বাছক, বা এবাৰ লিখক, পিছৰ বাবে ছেভ হৈ যাব।",
  "hp.details": "নম্বৰ আৰু তাৰিখ। প্ৰতি ফাইনেন্সিয়েল বছৰত নম্বৰ নিজে বাঢ়ে; নিজৰ ছিৰিজ থাকিলে সলাব পাৰে।",
  "hp.billto": "যাক বিল দিছে। নাম লিখিবলৈ আৰম্ভ কৰি ছেভ কৰা কাষ্টমাৰ বাছক, বা নতুন লিখক। GSTIN ৰ পৰা ষ্টেট ভৰি যায়; ষ্টেটে ঠিক কৰে CGST+SGST নে IGST।",
  "hp.vendor": "যি ছাপ্লায়াৰক অৰ্ডাৰ দিছে। ছেভ কৰা ছাপ্লায়াৰ বাছক বা নতুন লিখক।",
  "hp.supplier": "ৰেজিষ্ট্ৰেচন নথকা যাৰ পৰা কিনিলে। এই চেল্ফ ইনভইচত GST ৰিভাৰ্চ চাৰ্জত আপুনি নিজে দিয়ে।",
  "hp.consignee": "মাল ক্ৰেতাৰ বাহিৰে আন ঠাই বা মানুহলৈ গ'লেহে ভৰাওক।",
  "hp.items": "প্ৰতিটো আইটেম বা ছাৰ্ভিচৰ এশাৰী। ছেভ কৰা আইটেম বাছিলে ৰেট, HSN আৰু GST ভৰি যায়, বা নতুন লিখক। পৰিমাণ × ৰেটৰ পৰা ডিচকাউণ্ট বাদ দি টেক্সেবল ভেলু হয়।",
  "hp.notes": "চৰ্ত, বেংকৰ বিৱৰণ আৰু ছপা পৃষ্ঠাৰ ৰূপ। পিছৰ বাবে ডিফল্ট হিচাপে ছেভ হয়।",
  "hp.einv": "যিবোৰ বিজনেছে ই-ইনভইচ বা ই-ৱে বিল বনাবই লাগে: ফাইল ডাউনল'ড কৰক, চৰকাৰী প'ৰ্টেলত নিজৰ লগইনেৰে আপল'ড কৰক, তাৰ পিছত উত্তৰ ইয়াত ল'ড কৰক।",
  "hp.exp": "এক্সপ'ৰ্টৰ বাবে: শ্বিপিং বিল, প'ৰ্ট আৰু কাৰেন্সী। এক্সপ'ৰ্ট জিৰো-ৰেটেড: LUT থাকিলে GST নালাগে; নাথাকিলে IGST দি ৰিফাণ্ড পায়।",
  "hp.s.from": "যি আপোনাক টকা দিলে। ছেভ কৰা কাষ্টমাৰ বাছক বা নাম লিখক।",
  "hp.s.pay": "টকাৰ পৰিমাণ, তাৰিখ আৰু কেনেকৈ দিলে। আইনৰ সীমাতকৈ বেছি নগদত সতৰ্কবাণী আহে।",
