  "hp.s.ded": "PF, ESI, প্ৰফেচনেল টেক্স, TDS আৰু আন কটা। বুটামে এইবোৰ নিজে হিচাপ কৰিব পাৰে।",
  "hp.s.entries": "প্ৰতিটো সৰু নগদ খৰচ বা টপ-আপ, এশাৰীকৈ। চলিত বেলেঞ্চে কয় বাকচত কিমান থাকিব লাগে।",
  "hp.a.home": "আজিৰ চমু: পাবলগীয়া আৰু দিবলগীয়া টকা, বাকী বিল আৰু নতুন এণ্ট্ৰি।",
  "hp.a.sales": "প্ৰতিটো চেল আৰু প্ৰতিখন বিলত কিমান বাকী। ক'টেচন বা অৰ্ডাৰ ইয়াতে বিললৈ সলাওক।",
  "hp.a.buy": "পাৰ্চেজ বিল, ৰিটাৰ্ণ আৰু খৰচ। নিদিয়াবোৰ Dues ত দেখা যায়।",
  "hp.a.money": "অহা আৰু যোৱা টকা। প্ৰতিটো পেমেণ্ট তাৰ বিলৰ সৈতে জোৰক; বাকীখিনি আটাইতকৈ পুৰণি বিললৈ যায়।",
  "hp.a.dues": "কোনে আপোনাক দিব আৰু আপুনি কাক দিব, বিলৰ বয়স অনুসৰি। ইয়াৰ পৰাই নম্ৰ WhatsApp ৰিমাইণ্ডাৰ পঠিয়াওক।",
  "hp.a.parties": "প্ৰতিজন কাষ্টমাৰ আৰু ছাপ্লায়াৰৰ বেলেঞ্চ। ষ্টেটমেণ্টৰ বাবে খোলক।",
  "hp.a.cash": "আপোনাৰ এণ্ট্ৰিৰ পৰা হিচাপ কৰা হাতৰ নগদ আৰু বেংক বেলেঞ্চ।",
  "hp.a.khata": "সহজ বাকীৰ খাতা: প্ৰতিজন কাষ্টমাৰে কি ল'লে আৰু কি দিলে।",
  "hp.a.preg": "সকলো পাৰ্চেজ বিল এখন ৰেজিষ্টাৰত, ইনপুট টেক্স ক্ৰেডিটৰ বাবে GST সহ।",
  "hp.a.ebook": "গোটেই বছৰৰ খৰচ, প্ৰকাৰ আৰু মাহ অনুসৰি।",
  "hp.a.chq": "পোৱা আৰু দিয়া চেক: জমা, ক্লিয়াৰ বা বাউন্স।",
  "hp.a.books": "কেছ বুক, বেংক বুক আৰু ডে বুক, চলিত বেলেঞ্চ সহ।",
  "hp.m.biz": "আপোনাৰ নিজৰ বিজনেছ। ডিফল্টটো নতুন ডকুমেণ্টত ভৰি যায়।",
  "hp.m.party": "কাষ্টমাৰ আৰু ছাপ্লায়াৰ। প্ৰতিটো ডকুমেণ্ট টুলত পৰামৰ্শ হিচাপে আহে।",
  "hp.m.item": "মাল আৰু ছাৰ্ভিচ, ৰেট, HSN আৰু GST সহ। CSV ফাইলেৰে একেলগে বহুত ইমপ'ৰ্ট কৰক।",
