  "hp.m.settings": "সকলো টুলৰ বাবে ডিফল্ট বিজনেছ, নম্বৰ ছিৰিজ আৰু নতুন ডকুমেণ্টৰ ডিফল্ট।",
  "hp.m.backup": "আপোনাৰ ডেটা এই ব্ৰাউজাৰতে আছে। সঘনাই বেকআপ ফাইল ছেভ কৰক আৰু এই ডিভাইচৰ বাহিৰত ৰাখক।",
  "hp.lock": "সাধাৰণ বেকআপৰ দৰেই, কিন্তু পাছৱৰ্ডেৰে লক (AES-256)। পাছৱৰ্ড অবিহনে এই ফাইল কোনেও খুলিব নোৱাৰে।",
  "hp.acct": "একাউণ্টেণ্টৰ বাবে এটা .zip বনায়: Excel ৰেজিষ্টাৰ, Tally ফাইল আৰু ডকুমেণ্ট। আমি একো নপঠিয়াওঁ।",
